-- MANUAL: data-integrity constraints Prisma cannot express.
-- Emails are stored lower-cased so the unique index is effectively case-insensitive.
ALTER TABLE "users" ADD CONSTRAINT "users_email_lowercase_chk" CHECK ("email" = lower("email"));
-- Role/permission keys are machine identifiers.
ALTER TABLE "roles" ADD CONSTRAINT "roles_key_format_chk" CHECK ("key" ~ '^[a-z][a-z0-9_]*$');
ALTER TABLE "permissions" ADD CONSTRAINT "permissions_key_format_chk" CHECK ("key" ~ '^[a-z][a-z_]*:[a-z][a-z_]*$');
-- An ACTIVE user must be able to sign in.
ALTER TABLE "users" ADD CONSTRAINT "users_active_requires_password_chk" CHECK ("status" <> 'ACTIVE' OR "password_hash" IS NOT NULL);

-- MANUAL: the audit log is append-only. Rejecting UPDATE/DELETE/TRUNCATE at the database
-- means no application bug or ad-hoc query can silently rewrite history.
CREATE FUNCTION audit_logs_block_mutation() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'audit_logs is append-only: % is not permitted', TG_OP USING ERRCODE = 'integrity_constraint_violation';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER audit_logs_no_update_delete
  BEFORE UPDATE OR DELETE ON "audit_logs"
  FOR EACH ROW EXECUTE FUNCTION audit_logs_block_mutation();

CREATE TRIGGER audit_logs_no_truncate
  BEFORE TRUNCATE ON "audit_logs"
  FOR EACH STATEMENT EXECUTE FUNCTION audit_logs_block_mutation();
